pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public {
        c = new ModifierEntrancy();
    }

    function testFuzz_property(address actor) public {
        // actor must be the Bank whose supportsToken() returns the correct Nu Token hash.
        // Deploying Bank as the caller makes the external call succeed on the reference.
        Bank bank = new Bank();
        vm.prank(address(bank));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
